<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
  :root {
    --bg: #0d0d12;
    --panel: #1a1b26;
    --accent: #00e67a;
    --food: #ff5252;
    --text: #e0e0e0;
    --muted: #888;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { height: 100%; font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); }
  body { display: flex; align-items: center; justify-content: center; overflow: hidden; }
  .game-wrapper { display: flex; flex-direction: column; align-items: center; gap: 16px; }
  #score { font-size: 24px; font-weight: 600; color: var(--accent); }
  #snake {
    background: #11121d;
    border: 4px solid var(--panel);
    border-radius: 8px;
    display: block;
    width: 400px;
    height: 400px;
  }
  .controls { display: flex; gap: 12px; }
  button {
    background: var(--panel);
    color: var(--text);
    border: 2px solid var(--accent);
    border-radius: 6px;
    padding: 8px 18px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
  }
  button:hover { background: var(--accent); color: #000; }
  button:active { transform: scale(0.97); }
</style>
</head>
<body>
  <div class="game-wrapper">
    <div id="score">Score: 0</div>
    <canvas id="snake" width="400" height="400"></canvas>
    <div class="controls">
      <button id="start">Start</button>
      <button id="pause">Pause</button>
      <button id="reset">Reset</button>
    </div>
  </div>

<script>
/* ===== Snake Game Engine ===== */
(() => {
  const COLS = 20;
  const ROWS = 20;
  const CELL = 20; // CSS px per cell (20*20 = 400)

  let snake = [];
  let foodPos = [5, 5];
  let dir = 'right';
  let nextDir = dir;
  let alive = true;
  let scoreVal = 0;
  let autoTick = null;

  function init() {
    const mid = Math.floor(COLS / 2);
    snake = [
      [mid, mid],
      [mid - 1, mid],
      [mid - 2, mid]
    ];
    dir = 'right';
    nextDir = dir;
    foodPos = randomFreeCell();
    alive = true;
    scoreVal = 0;
    renderScore();
    draw();
  }

  function randomFreeCell() {
    const free = [];
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (!snake.some(s => s[0] === x && s[1] === y)) {
          free.push([x, y]);
        }
      }
    }
    if (free.length === 0) return null;
    return free[Math.floor(Math.random() * free.length)];
  }

  function tick() {
    if (!alive) return;

    dir = nextDir;

    const [hx, hy] = snake[0];
    const delta = {
      up: [0, -1],
      down: [0, 1],
      left: [-1, 0],
      right: [1, 0]
    };
    const [dx, dy] = delta[dir];
    const nx = hx + dx;
    const ny = hy + dy;

    // Wall collision
    if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) {
      alive = false;
      draw();
      stopAutoTick();
      return;
    }

    // Self collision
    if (snake.some(s => s[0] === nx && s[1] === ny)) {
      alive = false;
      draw();
      stopAutoTick();
      return;
    }

    const head = [nx, ny];
    const ate = (nx === foodPos[0] && ny === foodPos[1]);

    snake.unshift(head);
    if (ate) {
      scoreVal++;
      foodPos = randomFreeCell();
      renderScore();
    } else {
      snake.pop();
    }

    draw();
  }

  /* ===== Rendering ===== */
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');

  // High DPI crisp rendering
  const dpr = window.devicePixelRatio || 1;
  canvas.width = COLS * CELL;
  canvas.height = ROWS * CELL;
  canvas.style.width = (COLS * CELL) + 'px';
  canvas.style.height = (ROWS * CELL) + 'px';
  ctx.scale(dpr, dpr);

  function renderScore() {
    document.getElementById('score').textContent = 'Score: ' + scoreVal;
  }

  function draw() {
    // Clear
    ctx.fillStyle = '#11121d';
    ctx.fillRect(0, 0, COLS * CELL, ROWS * CELL);

    // Draw food
    if (foodPos) {
      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--food').trim();
      ctx.beginPath();
      const fx = foodPos[0] * CELL;
      const fy = foodPos[1] * CELL;
      ctx.arc(fx + CELL / 2, fy + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw snake
    snake.forEach((cell, i) => {
      const x = cell[0] * CELL;
      const y = cell[1] * CELL;
      ctx.fillStyle = (i === 0)
        ? getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()
        : '#2ecc90';
      ctx.fillRect(x + 1, y + 1, CELL - 2, CELL - 2);
    });
  }

  /* ===== Direction Control ===== */
  function setDir(d) {
    const opposites = { up: 'down', down: 'up', left: 'right', right: 'left' };
    // Ignore 180° reversal
    if (opposites[dir] === d || opposites[nextDir] === d) {
      return;
    }
    nextDir = d;
  }

  function setFood(x, y) {
    foodPos = [x, y];
    draw();
  }

  /* ===== Auto-Tick / Game Control ===== */
  function startAutoTick() {
    stopAutoTick();
    autoTick = setInterval(() => { if (alive) tick(); }, 120);
  }

  function stopAutoTick() {
    if (autoTick) clearInterval(autoTick);
    autoTick = null;
  }

  /* ===== Public API ===== */
  window.game = {
    w: COLS,
    h: ROWS,
    reset: init,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: () => snake.map(s => [s[0], s[1]]),
    food: () => (foodPos ? [foodPos[0], foodPos[1]] : null),
    alive: () => alive,
    score: () => scoreVal
  };

  /* ===== UI Button Handlers ===== */
  document.getElementById('start').addEventListener('click', startAutoTick);
  document.getElementById('pause').addEventListener('click', stopAutoTick);
  document.getElementById('reset').addEventListener('click', () => {
    stopAutoTick();
    init();
  });

  /* ===== Keyboard Controls ===== */
  document.addEventListener('keydown', (e) => {
    switch (e.key) {
      case 'ArrowUp':    e.preventDefault(); setDir('up');    break;
      case 'ArrowDown':  e.preventDefault(); setDir('down');  break;
      case 'ArrowLeft':  e.preventDefault(); setDir('left');  break;
      case 'ArrowRight': e.preventDefault(); setDir('right'); break;
    }
  });

  /* ===== Initialize ===== */
  init();
})();
</script>
</body>
</html>
